INSERT INTO `submissions` VALUES (1,'public class Solution {\n    public static void main(String[] args) {\n        int[] nums = {1, 2, 3};\n        System.out.println(sum(nums));\n    }\n    public static int sum(int[] nums) {\n        int total = 0;\n        for (int n : nums) total += n;\n        return total;\n    }\n}','Java',NULL,95.00,'auto_graded','2026-05-02 10:00:00.000000','Submitted via online IDE','Excellent solution! Clean and efficient.',NULL,1,16,10),(2,'public class Solution { public static int sum(int[] a) { int s=0; for(int x:a) s+=x; return s; } }','Java',NULL,90.00,'graded','2026-05-20 10:00:00.000000','IDE submission','Good solution.',NULL,1,16,13);
